/**
 * 按组件 type 获取结构化规格。
 */
export function getComponentSpec(type: string): Record<string, unknown> | null {
  return (COMPONENT_SPEC_BY_TYPE as Record<string, Record<string, unknown>>)[type] ?? null
}

